package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;
/** Global user/profile/agent registry. Does not depend on the selected goal. */
final class NubiMyPageUi {
 final NubiCompanionUi ui;final GoalChatUi c;final GoalAgentActivity a;
 NubiMyPageUi(NubiCompanionUi ui){this.ui=ui;c=ui.c;a=ui.a;}
 void show(){ui.sideBody.removeAllViews();ui.add("학교생활 연결하기","Blackboard · 에타 · 포털 · 학사메일 · GPT","시작하기",()->ui.select("학교 시작하기"));android.content.SharedPreferences p=a.getSharedPreferences("nubi_profile",0);ui.add("내 정보",p.getString("name","이름을 알려주세요")+" · "+a.getSharedPreferences("nubi_campus",0).getString("school","UNIST"),"수정",this::edit);if(!c.goalId.isEmpty())ui.add("돌아갈 대화",c.preset.name+" · "+c.goalTitle(),"대화 이어가기",()->ui.select("대화"));ui.muted("내 누비 6 · 선택한 대화와 실행 중인 작업은 달라요");for(GoalRules.Preset preset:GoalRules.PRESETS){int count=0;for(JSONObject goal:a.store.goals())if(!GoalStore.fixture(goal)&&goal.optString("character").equals(preset.id))count++;String status=count==0?"아직 목표가 없어요":"목표 "+count+"개";if(preset.id.equals(c.character))status+=" · 선택한 대화";if(a.runs!=null&&a.runs.active()!=null&&preset.id.equals(a.runs.active().optString("character")))status+=" · 작업 진행 중";ui.add(preset.name+" · "+preset.emoji,status+"\n"+preset.title,"목표 보기",()->ui.agentGoals(preset.id));}ui.add("서비스 연결·기기 설정","메일·포털·탐색 연결 상태와 기기 내 모델","관리",()->ui.select("연결·기기 설정"));ui.add("개인화 데이터","수집 상태·범위·중지·삭제","확인",()->ui.select("수집 설정"));ui.add("기기 기록 관리","이 앱의 목표·대화·할 일·웹 기록","관리",ui::clearLocalData);}
 void edit(){LinearLayout form=ui.c.box(-1,16);EditText name=new EditText(a),school=new EditText(a),region=new EditText(a);android.content.SharedPreferences p=a.getSharedPreferences("nubi_profile",0);name.setHint("이름 (선택)");name.setText(p.getString("name",""));school.setHint("학교");school.setText(a.getSharedPreferences("nubi_campus",0).getString("school","UNIST"));region.setHint("기본 지역");region.setText(p.getString("region","울산"));for(EditText e:new EditText[]{name,school,region}){e.setSingleLine(true);form.addView(e);}new AlertDialog.Builder(a).setTitle("내 정보 · 모든 누비가 함께 사용해요").setView(form).setNegativeButton("취소",null).setPositiveButton("저장",(d,w)->{if(name.length()>30||school.length()>100||region.length()>100){a.toast("이름 30자, 학교·지역 100자 이내로 적어주세요.");return;}p.edit().putString("name",name.getText().toString().trim()).putString("region",region.getText().toString().trim()).apply();a.getSharedPreferences("nubi_campus",0).edit().putString("school",school.getText().toString().trim()).apply();show();}).show();}
}
